// 簡易融合の整理と異次元の女戦士QAの文体統一。
(function () {
  const instant = window.RULINGS.find(card => card.name === "簡易融合");
  const lady = window.RULINGS.find(card => card.name === "異次元の女戦士");
  if (!instant || !lady) throw new Error("Missing target cards");
  instant.overview = "■発動と特殊召喚について\n▷発動する際に、コストとして1000ライフポイントを払う。1ターンに1枚しか発動できない。\n▷エクストラデッキからレベル5以下の融合モンスター1体を、融合召喚扱いで特殊召喚する。対象を取らない。\n▷《デス・デーモン・ドラゴン》など、「このカードの融合召喚は上記のカードでしか行えない」と記された融合モンスターは特殊召喚できない。\n▷特殊召喚で効果処理は完了する。特殊召喚したモンスターには、攻撃できず、エンドフェイズに破壊される状態が適用される。\n\n■攻撃制限とエンドフェイズの破壊\n▷エンドフェイズに破壊する処理では、チェーンブロックを作らない。\n▷特殊召喚したモンスターのコントロールが相手に移った場合も、エンドフェイズに破壊する。\n▷裏側表示になった場合や、一時的に除外されるなどしてフィールドを離れた場合、攻撃制限とエンドフェイズに破壊する状態は解除される。\n▷破壊を防ぐ効果や身代わりによってエンドフェイズの破壊を免れた場合、次のターン以降は破壊されないが、攻撃制限は残る。";
  instant.qa = [
  {
    "question": "《デス・デーモン・ドラゴン》など、「このカードの融合召喚は上記のカードでしか行えない」と記された融合モンスターを特殊召喚できますか？",
    "answer": "いいえ、できません。このカードによる特殊召喚は融合召喚扱いのため、その制限を満たさない特殊召喚は行えません。",
    "managementId": "R-S3RVA58A9X"
  },
  {
    "question": "特殊召喚したモンスターを《月の書》で裏側守備表示にした場合、エンドフェイズに破壊されますか？",
    "answer": "いいえ、破壊されません。裏側表示になったことで、攻撃制限とエンドフェイズに破壊する状態は解除されます。その後、表側表示に戻った場合は攻撃することもできます。",
    "managementId": "R-PRQC9WKDV5"
  },
  {
    "question": "特殊召喚したモンスターを《亜空間物質転送装置》で一時的に除外した場合、戻った後に攻撃できますか？ また、エンドフェイズに破壊されますか？",
    "answer": "戻った後は攻撃でき、エンドフェイズにも破壊されません。一度フィールドを離れたことで、攻撃制限とエンドフェイズに破壊する状態は解除されます。",
    "managementId": "R-M3ZW5J9F35"
  },
  {
    "question": "《奇跡のピラミッド》やユニオンの身代わり等でエンドフェイズの破壊を免れた場合、次のターン以降は攻撃できますか？ また、再びエンドフェイズに破壊されますか？",
    "answer": "次のターン以降も攻撃できませんが、エンドフェイズに破壊する処理は再び行いません。",
    "managementId": "R-XC8H6YYZCE"
  },
  {
    "question": "このカードの発動を《神の宣告》等で無効にされた場合、同じターンに別の《簡易融合》を発動できますか？",
    "answer": "はい、発動できます。カードの発動が無効になっているため、もう1枚発動できます。",
    "managementId": "R-J2YLVJJWHV"
  },
  {
    "question": "このカードで特殊召喚したモンスターに《禁じられた聖槍》を適用した場合、エンドフェイズの破壊を回避できますか？",
    "answer": "いいえ、回避できません。《禁じられた聖槍》の適用終了と、このカードによる破壊処理のどちらを先に行っても、破壊されます。\n\n[[補足:特殊召喚後に魔法カードの効果を受けなくなった場合]]\nこのカードで特殊召喚した時点で、攻撃できない状態と、エンドフェイズに破壊する効果が既に適用されたものとして扱います。\n\nそのため、後から《禁じられた聖槍》によって魔法カードの効果を受けなくなっても、既に適用された破壊を回避することはできません。\n[[/補足]]",
    "environments": [
      "1103"
    ],
    "managementId": "R-T2LFNVEU"
  }
];
  instant.specialTags = [...new Set([...(instant.specialTags || []), "【フュージョン】"])];
  const answers = {
  "R-S6T5J87HQU": "はい、どちらの場合も発動できます。\n\n[[補足:戦闘相手による処理の違い]]\n▷《スフィア・ボム 球体時限爆弾》の場合：装備カードになった後で、このカードの効果を発動できます。\n▷《伝説の柔術家》の場合：このカードの効果を発動すれば、両方を除外します。発動しなければ、このカードは《伝説の柔術家》の効果でデッキの一番上に戻ります。\n[[/補足]]",
  "R-KGS5YQWVJU": "はい、フィールドで発動できます。このカードは《レッド・デーモンズ・ドラゴン》の効果で破壊され、相手の《レッド・デーモンズ・ドラゴン》のみ除外されます。\n\n[[補足:この場合の効果処理]]\n▷《群雄割拠》に関連する処理と同様、この場合は例外的に、このカードの効果処理を墓地で行う扱いになります。\n[[/補足]]",
  "R-6BYC24FAKN": "いいえ、行われません。\n\n[[補足:ダメージステップ中の処理順]]\n▷[DS表④ダメージ計算後]：《イビリチュア・メロウガイスト》の効果が発動します。この時点では、まだデッキには戻しません。\n▷[DS表⑤戦闘結果解決時]：このカードの効果を発動し、両方を除外します。\n▷[DS表⑥ダメージステップ終了時]：デッキに戻す処理は行われません。\n[[/補足]]",
  "R-Y83T7": "先にこのカードの効果で両方を除外します。《スノーマン・イーター》が対象に取ったこのカードは既にフィールドにいないため、破壊する処理は行われません。\n\n[[補足:チェーンの組み方と処理順]]\n▷[DS表⑤戦闘結果解決時]に、強制効果の《スノーマン・イーター》がチェーン1、任意効果のこのカードがチェーン2になります。\n▷チェーン2で両方を除外し、その後、チェーン1を処理します。《スノーマン・イーター》の効果は、フィールドで発動した扱いです。\n▷自分フィールドにほかのモンスターがいる場合も、ターンプレイヤーがこのカードの効果を発動するか決めた後、非ターンプレイヤーが《スノーマン・イーター》の対象を選びます。《ライトロード・ハンター ライコウ》の場合も同様です。\n[[/補足]]"
};
  for (const [id, answer] of Object.entries(answers)) {
    const entry = lady.qa.find(entry => entry.managementId === id);
    if (!entry) throw new Error("Missing QA: " + id);
    entry.answer = answer;
  }
})();
